import random

for _ in range(1000):
    n = 4 # Try small n first
    c_seq = [random.uniform(0.5, 1.0) for _ in range(n)]
    if is_forced_to_cover(c_seq):
        print(f"Found sequence: {c_seq}")
        break
else:
    print("No sequence found for n=4")

